from dataclasses import dataclass
import json
@dataclass(frozen=True, slots=True, repr=False)
class Ok:
    _0: object
    def __repr__(self):
        return f"Ok({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class Error:
    _0: object
    def __repr__(self):
        return f"Error({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class Some:
    _0: object
    def __repr__(self):
        return f"Some({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class None_:
    def __repr__(self):
        return "None_"
_None_ = None_()
@dataclass(frozen=True, slots=True, repr=False)
class _Exception:
    errorKind: str
    errorMessage: str
    def __repr__(self):
        return f"_Exception({self.errorKind!r}, {self.errorMessage!r})"
def _pf_dec_decode_string(dec, s):
    try:
        return Ok(dec(json.loads(s)))
    except Exception as e:
        return Error(_Exception(type(e).__name__, str(e)))
def _pf_dec_fail(msg):
    def go(v):
        raise ValueError(msg)
    return go
def _pf_dec_int(v):
    if isinstance(v, int) and not isinstance(v, bool):
        return v
    raise ValueError("expected an int, got " + type(v).__name__)
def _pf_dec_nullable(dec):
    def go(v):
        return None_() if v is None else Some(dec(v))
    return go
def _pf_dec_one_of(decs):
    def go(v):
        def _try(i):
            if i >= len(decs):
                raise ValueError("Decode.oneOf: no decoder matched")
            try:
                return decs[i](v)
            except Exception:
                return _try(i + 1)
        return _try(0)
    return go
def _pf_dec_succeed(x):
    def go(v):
        return x
    return go
def runWith(d, s):
    return _pf_dec_decode_string(d, s)
def show(r):
    if isinstance(r, Ok):
        v = r._0
        return f"ok {v}"
    else:
        e = r._0
        return f"error {e.errorKind}: {e.errorMessage}"
maybeInt = _pf_dec_nullable(_pf_dec_int)
never = _pf_dec_fail("never decodes")
print(show(runWith(maybeInt, "null")))
print(show(runWith(maybeInt, "7")))
print(show(runWith(never, "3")))
print(show(runWith(_pf_dec_one_of([never, _pf_dec_succeed(1)]), "3")))
